17	import {
18	  coreServices,
19	  createBackendPlugin,
20	} from '@backstage/backend-plugin-api';
21	import {
22	  LunrSearchEngine,
23	  RegisterCollatorParameters,
24	  RegisterDecoratorParameters,
25	  SearchEngine,
26	} from '@backstage/plugin-search-backend-node';
27	import {
28	  SearchEngineRegistryExtensionPoint,
29	  searchEngineRegistryExtensionPoint,
30	  searchIndexRegistryExtensionPoint,
31	  SearchIndexRegistryExtensionPoint,
32	  searchIndexServiceRef,
33	} from '@backstage/plugin-search-backend-node/alpha';
34	
35	import { createRouter } from './service/router';
36	
37	class SearchIndexRegistry implements SearchIndexRegistryExtensionPoint {
38	  private collators: RegisterCollatorParameters[] = [];
39	  private decorators: RegisterDecoratorParameters[] = [];
40	
41	  public addCollator(options: RegisterCollatorParameters): void {
42	    this.collators.push(options);
43	  }
44	
45	  public addDecorator(options: RegisterDecoratorParameters): void {
46	    this.decorators.push(options);
47	  }
48	
49	  public getCollators(): RegisterCollatorParameters[] {
50	    return this.collators;
51	  }
52	
53	  public getDecorators(): RegisterDecoratorParameters[] {
54	    return this.decorators;
55	  }
56	}
57	
58	class SearchEngineRegistry implements SearchEngineRegistryExtensionPoint {
59	  private searchEngine: SearchEngine | null = null;
60	
61	  public setSearchEngine(searchEngine: SearchEngine): void {
62	    if (this.searchEngine) {
63	      throw new Error('Multiple Search engines is not supported at this time');
64	    }
65	    this.searchEngine = searchEngine;
66	  }
67	
68	  public getSearchEngine(): SearchEngine | null {
69	    return this.searchEngine;
70	  }
71	}
72	
73	/**
74	 * The Search plugin is responsible for starting search indexing processes and return search results.
75	 * @public
76	 */
77	export default createBackendPlugin({
78	  pluginId: 'search',
79	  register(env) {
80	    const searchIndexRegistry = new SearchIndexRegistry();
81	    env.registerExtensionPoint(
82	      searchIndexRegistryExtensionPoint,
83	      searchIndexRegistry,
84	    );
85	
86	    const searchEngineRegistry = new SearchEngineRegistry();
87	    env.registerExtensionPoint(
88	      searchEngineRegistryExtensionPoint,
89	      searchEngineRegistry,
90	    );
91	
92	    env.registerInit({
93	      deps: {
94	        logger: coreServices.logger,
95	        config: coreServices.rootConfig,
96	        discovery: coreServices.discovery,
97	        permissions: coreServices.permissions,
98	        auth: coreServices.auth,
99	        http: coreServices.httpRouter,
100	        httpAuth: coreServices.httpAuth,
101	        lifecycle: coreServices.rootLifecycle,
102	        searchIndexService: searchIndexServiceRef,
103	      },
104	      async init({
105	        config,
106	        logger,
107	        discovery,
108	        permissions,
109	        auth,
110	        http,
111	        httpAuth,
112	        lifecycle,
113	        searchIndexService,
114	      }) {
115	        let searchEngine = searchEngineRegistry.getSearchEngine();
116	        if (!searchEngine) {
117	          searchEngine = new LunrSearchEngine({
118	            logger,
119	          });
120	        }
121	
122	        const collators = searchIndexRegistry.getCollators();
123	        const decorators = searchIndexRegistry.getDecorators();
124	        searchIndexService.init({
125	          searchEngine: searchEngine!,
126	          collators,
127	          decorators,
128	        });
129	
130	        lifecycle.addStartupHook(async () => {
131	          await searchIndexService.start();
132	        });
133	
134	        lifecycle.addShutdownHook(async () => {
135	          await searchIndexService.stop();
136	        });
137	
138	        const router = await createRouter({
139	          config,
140	          discovery,
141	          permissions,
142	          auth,
143	          httpAuth,
144	          logger,
145	          engine: searchEngine,
146	          types: searchIndexService.getDocumentTypes(),
147	        });
148	
149	        http.use(router);
150	      },
151	    });
152	  },
153	});
