17	import express from 'express';
18	import { z } from 'zod/v3';
19	import { InputError } from '@backstage/errors';
20	import { Config } from '@backstage/config';
21	import { JsonObject, JsonValue } from '@backstage/types';
22	import {
23	  PermissionAuthorizer,
24	  PermissionEvaluator,
25	  toPermissionEvaluator,
26	} from '@backstage/plugin-permission-common';
27	import {
28	  DocumentTypeInfo,
29	  IndexableResultSet,
30	  SearchResultSet,
31	} from '@backstage/plugin-search-common';
32	import { SearchEngine } from '@backstage/plugin-search-backend-node';
33	import { AuthorizedSearchEngine } from './AuthorizedSearchEngine';
34	import { createOpenApiRouter } from '../schema/openapi';
35	import {
36	  AuthService,
37	  DiscoveryService,
38	  HttpAuthService,
39	  LoggerService,
40	} from '@backstage/backend-plugin-api';
41	
42	const jsonObjectSchema: z.ZodSchema<JsonObject> = z.lazy(() => {
43	  const jsonValueSchema: z.ZodSchema<JsonValue> = z.lazy(() =>
44	    z.union([
45	      z.string(),
46	      z.number(),
47	      z.boolean(),
48	      z.null(),
49	      z.array(jsonValueSchema),
50	      jsonObjectSchema,
51	    ]),
52	  );
53	
54	  return z.record(jsonValueSchema);
55	});
56	
57	/**
58	 * @internal
59	 */
60	export type RouterOptions = {
61	  engine: SearchEngine;
62	  types: Record<string, DocumentTypeInfo>;
63	  discovery?: DiscoveryService;
64	  permissions: PermissionEvaluator | PermissionAuthorizer;
65	  config: Config;
66	  logger: LoggerService;
67	  auth: AuthService;
68	  httpAuth: HttpAuthService;
69	};
70	
71	const defaultMaxPageLimit = 100;
72	const defaultMaxTermLength = 100;
73	const allowedLocationProtocols = ['http:', 'https:'];
74	
75	/**
76	 * @internal
77	 */
78	export async function createRouter(
79	  options: RouterOptions,
80	): Promise<express.Router> {
81	  const router = await createOpenApiRouter();
82	  const {
83	    engine: inputEngine,
84	    types,
85	    permissions,
86	    config,
87	    logger,
88	    auth,
89	    httpAuth,
90	  } = options;
91	
92	  const maxPageLimit =
93	    config.getOptionalNumber('search.maxPageLimit') ?? defaultMaxPageLimit;
94	
95	  const maxTermLength =
96	    config.getOptionalNumber('search.maxTermLength') ?? defaultMaxTermLength;
97	
98	  const requestSchema = z.object({
99	    term: z
100	      .string()
101	      .refine(
102	        term => term.length <= maxTermLength,
103	        term => ({
104	          message: `The term length "${term.length}" is greater than "${maxTermLength}"`,
105	        }),
106	      )
107	      .default(''),
108	    filters: jsonObjectSchema.optional(),
109	    types: z
110	      .array(z.string().refine(type => Object.keys(types).includes(type)))
111	      .optional(),
112	    pageCursor: z.string().optional(),
113	    pageLimit: z
114	      .number()
115	      .refine(
116	        pageLimit => pageLimit <= maxPageLimit,
117	        pageLimit => ({
118	          message: `The page limit "${pageLimit}" is greater than "${maxPageLimit}"`,
119	        }),
120	      )
121	      .optional(),
122	  });
123	
124	  let permissionEvaluator: PermissionEvaluator;
125	  if ('authorizeConditional' in permissions) {
126	    permissionEvaluator = permissions as PermissionEvaluator;
127	  } else {
128	    logger.warn(
129	      'PermissionAuthorizer is deprecated. Please use an instance of PermissionEvaluator instead of PermissionAuthorizer in PluginEnvironment#permissions',
130	    );
131	    permissionEvaluator = toPermissionEvaluator(permissions);
132	  }
133	
134	  const engine = config.getOptionalBoolean('permission.enabled')
135	    ? new AuthorizedSearchEngine(
136	        inputEngine,
137	        types,
138	        permissionEvaluator,
139	        auth,
140	        config,
141	      )
142	    : inputEngine;
143	
144	  const filterResultSet = ({ results, ...resultSet }: SearchResultSet) => ({
145	    ...resultSet,
146	    results: results.filter(result => {
147	      const protocol = new URL(result.document.location, 'https://example.com')
148	        .protocol;
149	      const isAllowed = allowedLocationProtocols.includes(protocol);
150	      if (!isAllowed) {
151	        logger.info(
152	          `Rejected search result for "${result.document.title}" as location protocol "${protocol}" is unsafe`,
153	        );
154	      }
155	      return isAllowed;
156	    }),
157	  });
158	
159	  const toSearchResults = (resultSet: IndexableResultSet): SearchResultSet => ({
160	    ...resultSet,
161	    results: resultSet.results.map(result => ({
162	      ...result,
163	      document: {
164	        ...result.document,
165	        authorization: undefined,
166	      },
167	    })),
168	  });
169	
170	  router.get('/query', async (req, res) => {
171	    const parseResult = requestSchema.passthrough().safeParse(req.query);
172	
173	    if (!parseResult.success) {
174	      throw new InputError(`Invalid query string: ${parseResult.error}`);
175	    }
176	
177	    const query = parseResult.data;
178	
179	    logger.info(
180	      `Search request received: term="${query.term}", filters=${JSON.stringify(
181	        query.filters,
182	      )}, types=${query.types ? query.types.join(',') : ''}, pageCursor=${
183	        query.pageCursor ?? ''
184	      }`,
185	    );
186	
187	    try {
188	      const credentials = await httpAuth.credentials(req);
189	      const { token } = await auth.getPluginRequestToken({
190	        onBehalfOf: credentials,
191	        targetPluginId: 'search',
192	      });
193	      const resultSet = await engine?.query(query, {
194	        token,
195	        credentials,
196	      });
197	
198	      res.json(filterResultSet(toSearchResults(resultSet)));
199	    } catch (error) {
200	      // Log the error message here, but don't expose it to the user in the response
201	      logger.error(
202	        `There was a problem performing the search query: ${error.message}`,
203	      );
204	      if (error.name === 'MissingIndexError') {
205	        // re-throw and let the default error handler middleware captures it and serializes it with the right response code on the standard form
206	        throw error;
207	      }
208	
209	      // If the error is not a MissingIndexError, we want to throw a generic error without the error message as it may leak internal information
210	      throw new Error(`There was a problem performing the search query`);
211	    }
212	  });
213	
214	  return router;
215	}
