import { LoggerService } from '@backstage/backend-plugin-api';
import { ActionsRegistryService } from '@backstage/backend-plugin-api/alpha';
import { SearchEngine } from '@backstage/plugin-search-backend-node';
import { SearchIndexService } from '@backstage/plugin-search-backend-node/alpha';
import { JsonObject, JsonValue } from '@backstage/types';

const allowedLocationProtocols = ['http:', 'https:'];

export const createQueryAction = ({
  engine,
  actionsRegistry,
  searchIndexService,
  logger,
}: {
  engine: SearchEngine;
  actionsRegistry: ActionsRegistryService;
  searchIndexService: SearchIndexService;
  logger: LoggerService;
}): void => {
  const documentTypes = Object.keys(searchIndexService.getDocumentTypes());
  const knownTypes = documentTypes.length
    ? `Known document types: ${documentTypes.join(', ')}.`
    : 'No document types are currently registered.';

  actionsRegistry.register({
    name: 'search-query',
    title: 'Search Query',
    description: `
Query the Backstage search engine for documents matching a search term.

Provide a free-text \`term\` to search for. Optionally narrow the search to
specific document \`types\`, apply \`filters\`, and paginate using \`pageLimit\`
and \`pageCursor\`.

Each result has a \`type\` and a \`document\` containing at least a \`title\`,
\`text\`, and \`location\`. Use \`nextPageCursor\` together with \`hasMoreResults\`
to fetch subsequent pages.

${knownTypes}
    `,
    attributes: {
      destructive: false,
      readOnly: true,
      idempotent: true,
    },
    schema: {
      input: z => {
        const jsonValueSchema: any = z.lazy(() =>
          z.union([
            z.string(),
            z.number(),
            z.boolean(),
            z.null(),
            z.array(jsonValueSchema),
            z.record(jsonValueSchema),
          ]),
        );
        const jsonObjectSchema = z.record(jsonValueSchema);

        return z.object({
          term: z.string().describe('The free-text term to search for.'),
          types: z
            .array(z.string())
            .optional()
            .describe(
              'Optional list of document types to restrict the search to.',
            ),
          filters: jsonObjectSchema
            .optional()
            .describe(
              'Optional filters to apply to the search, as a nested object of field values.',
            ),
          pageLimit: z
            .number()
            .optional()
            .describe('Maximum number of results to return per page.'),
          pageCursor: z
            .string()
            .optional()
            .describe(
              'Cursor used to fetch a specific page of results, returned as `nextPageCursor` from a previous query.',
            ),
        });
      },
      output: z =>
        z.object({
          results: z
            .array(
              z.object({
                type: z.string().describe('The type of the document.'),
                document: z
                  .object({
                    title: z.string().describe('The title of the document.'),
                    text: z.string().describe('The text of the document.'),
                    location: z
                      .string()
                      .describe('The location (URL) of the document.'),
                  })
                  .passthrough()
                  .describe('The matched document.'),
              }),
            )
            .describe('The list of matching search results.'),
          nextPageCursor: z
            .string()
            .optional()
            .describe('Cursor used to fetch the next page of results.'),
          totalItems: z
            .number()
            .optional()
            .describe('Total number of results matching the query.'),
          hasMoreResults: z
            .boolean()
            .describe('Whether more results are available on subsequent pages.'),
        }),
    },
    action: async ({ input }) => {
      const resultSet = await engine.query({
        term: input.term,
        types: input.types,
        filters: input.filters as JsonObject | undefined,
        pageLimit: input.pageLimit,
        pageCursor: input.pageCursor,
      });

      const results = resultSet.results
        .filter(result => {
          const protocol = new URL(
            result.document.location,
            'https://example.com',
          ).protocol;
          const isAllowed = allowedLocationProtocols.includes(protocol);
          if (!isAllowed) {
            logger.info(
              `Rejected search result for "${result.document.title}" as location protocol "${protocol}" is unsafe`,
            );
          }
          return isAllowed;
        })
        .map(({ document }) => {
          const { authorization, ...rest } = document as JsonObject & {
            authorization?: JsonValue;
          };
          return {
            type: (document as unknown as { type?: string }).type as string,
            document: rest,
          };
        });

      return {
        output: {
          results: resultSet.results
            .filter(result => {
              const protocol = new URL(
                result.document.location,
                'https://example.com',
              ).protocol;
              const isAllowed = allowedLocationProtocols.includes(protocol);
              if (!isAllowed) {
                logger.info(
                  `Rejected search result for "${result.document.title}" as location protocol "${protocol}" is unsafe`,
                );
              }
              return isAllowed;
            })
            .map(result => {
              const { authorization, ...document } = result.document as Record<
                string,
                unknown
              >;
              return {
                type: result.type,
                document: document as {
                  title: string;
                  text: string;
                  location: string;
                  [key: string]: any;
                },
              };
            }),
          nextPageCursor: resultSet.nextPageCursor,
          totalItems: resultSet.numberOfResults,
          hasMoreResults: !!resultSet.nextPageCursor,
        },
      };
    },
  });
};
